    (1298, "Coordonnées d'un point du cercle trigonométrique", 1, 'On sait que $\\cos\\left(\\dfrac{\\pi}{3}\\right) = \\dfrac{1}{2}$ et $\\sin\\left(\\dfrac{\\pi}{3}\\right) = \\dfrac{\\sqrt{3}}{2}$. En utilisant les symétries du cercle trigonométrique, déterminer $\\cos\\left(\\pi+\\dfrac{\\pi}{3}\\right)$.', '$\\cos\\left(\\pi+\\dfrac{\\pi}{3}\\right) = -\\dfrac{1}{2}$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos(\\pi+a) = -\\cos(a)$ et $\\sin(\\pi+a) = -\\sin(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{3}$, on obtient $\\cos\\left(\\pi+\\dfrac{\\pi}{3}\\right) = -\\dfrac{1}{2}$.')),
    (1299, "Coordonnées d'un point du cercle trigonométrique", 1, 'On sait que $\\cos\\left(\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$ et $\\sin\\left(\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$. En utilisant les symétries du cercle trigonométrique, déterminer $\\cos\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{4}\\right)$.', '$\\cos\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos\\left(\\dfrac{\\pi}{2}-a\\right) = \\sin(a)$ et $\\sin\\left(\\dfrac{\\pi}{2}-a\\right) = \\cos(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{4}$, on obtient $\\cos\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$.')),
    (1300, "Coordonnées d'un point du cercle trigonométrique", 1, 'On sait que $\\cos\\left(\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$ et $\\sin\\left(\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$. En utilisant les symétries du cercle trigonométrique, déterminer $\\cos\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{4}\\right)$ et $\\sin\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{4}\\right)$.', '$\\cos\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$ et $\\sin\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos\\left(\\dfrac{\\pi}{2}-a\\right) = \\sin(a)$ et $\\sin\\left(\\dfrac{\\pi}{2}-a\\right) = \\cos(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{4}$, on obtient $\\cos\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$ et $\\sin\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$.')),
    (1301, "Coordonnées d'un point du cercle trigonométrique", 1, 'On sait que $\\cos\\left(\\dfrac{\\pi}{3}\\right) = \\dfrac{1}{2}$ et $\\sin\\left(\\dfrac{\\pi}{3}\\right) = \\dfrac{\\sqrt{3}}{2}$. En utilisant les symétries du cercle trigonométrique, déterminer $\\cos\\left(-\\dfrac{\\pi}{3}\\right)$.', '$\\cos\\left(-\\dfrac{\\pi}{3}\\right) = \\dfrac{1}{2}$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos(-a) = \\cos(a)$ et $\\sin(-a) = -\\sin(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{3}$, on obtient $\\cos\\left(-\\dfrac{\\pi}{3}\\right) = \\dfrac{1}{2}$.')),
    (1302, "Coordonnées d'un point du cercle trigonométrique", 1, 'On sait que $\\cos\\left(\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$ et $\\sin\\left(\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$. En utilisant les symétries du cercle trigonométrique, déterminer $\\sin\\left(\\pi-\\dfrac{\\pi}{4}\\right)$.', '$\\sin\\left(\\pi-\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos(\\pi-a) = -\\cos(a)$ et $\\sin(\\pi-a) = \\sin(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{4}$, on obtient $\\sin\\left(\\pi-\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$.')),
