    (1309, "Coordonnées d'un point du cercle trigonométrique", 1, 'On sait que $\\cos\\left(\\dfrac{\\pi}{3}\\right) = \\dfrac{1}{2}$ et $\\sin\\left(\\dfrac{\\pi}{3}\\right) = \\dfrac{\\sqrt{3}}{2}$. En utilisant les symétries du cercle trigonométrique, déterminer $\\sin\\left(-\\dfrac{\\pi}{3}\\right)$.', '$\\sin\\left(-\\dfrac{\\pi}{3}\\right) = -\\dfrac{\\sqrt{3}}{2}$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos(-a) = \\cos(a)$ et $\\sin(-a) = -\\sin(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{3}$, on obtient $\\sin\\left(-\\dfrac{\\pi}{3}\\right) = -\\dfrac{\\sqrt{3}}{2}$.')),
    (1310, "Coordonnées d'un point du cercle trigonométrique", 2, 'On sait que $\\cos\\left(\\dfrac{\\pi}{6}\\right) = \\dfrac{\\sqrt{3}}{2}$ et $\\sin\\left(\\dfrac{\\pi}{6}\\right) = \\dfrac{1}{2}$. En utilisant les symétries du cercle trigonométrique, déterminer $\\cos\\left(\\pi+\\dfrac{\\pi}{6}\\right)$ et $\\sin\\left(\\pi+\\dfrac{\\pi}{6}\\right)$.', '$\\cos\\left(\\pi+\\dfrac{\\pi}{6}\\right) = -\\dfrac{\\sqrt{3}}{2}$ et $\\sin\\left(\\pi+\\dfrac{\\pi}{6}\\right) = -\\dfrac{1}{2}$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos(\\pi+a) = -\\cos(a)$ et $\\sin(\\pi+a) = -\\sin(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{6}$, on obtient $\\cos\\left(\\pi+\\dfrac{\\pi}{6}\\right) = -\\dfrac{\\sqrt{3}}{2}$ et $\\sin\\left(\\pi+\\dfrac{\\pi}{6}\\right) = -\\dfrac{1}{2}$.')),
    (1311, "Coordonnées d'un point du cercle trigonométrique", 2, 'On sait que $\\cos\\left(\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$ et $\\sin\\left(\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$. En utilisant les symétries du cercle trigonométrique, déterminer $\\sin\\left(-\\dfrac{\\pi}{4}\\right)$.', '$\\sin\\left(-\\dfrac{\\pi}{4}\\right) = -\\dfrac{\\sqrt{2}}{2}$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos(-a) = \\cos(a)$ et $\\sin(-a) = -\\sin(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{4}$, on obtient $\\sin\\left(-\\dfrac{\\pi}{4}\\right) = -\\dfrac{\\sqrt{2}}{2}$.')),
    (1312, "Coordonnées d'un point du cercle trigonométrique", 2, "On sait que $\\cos\\left(\\dfrac{\\pi}{2}\\right) = 0$ et $\\sin\\left(\\dfrac{\\pi}{2}\\right) = 1$. En utilisant les symétries du cercle trigonométrique, déterminer $\\cos\\left(\\pi+\\dfrac{\\pi}{2}\\right)$ et $\\sin\\left(\\pi+\\dfrac{\\pi}{2}\\right)$, puis en déduire dans quel quadrant se situe le point du cercle trigonométrique associé à l'angle $\\pi+\\dfrac{\\pi}{2}$.", "$\\cos\\left(\\pi+\\dfrac{\\pi}{2}\\right) = 0$ et $\\sin\\left(\\pi+\\dfrac{\\pi}{2}\\right) = -1$ ; le point est sur l'axe des ordonnées", "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos(\\pi+a) = -\\cos(a)$ et $\\sin(\\pi+a) = -\\sin(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{2}$, on obtient $\\cos\\left(\\pi+\\dfrac{\\pi}{2}\\right) = 0$ et $\\sin\\left(\\pi+\\dfrac{\\pi}{2}\\right) = -1$.')),
    (1313, "Coordonnées d'un point du cercle trigonométrique", 2, 'On sait que $\\cos\\left(\\dfrac{\\pi}{2}\\right) = 0$ et $\\sin\\left(\\dfrac{\\pi}{2}\\right) = 1$. En utilisant les symétries du cercle trigonométrique, déterminer $\\cos\\left(\\pi-\\dfrac{\\pi}{2}\\right)$ et $\\sin\\left(\\pi-\\dfrac{\\pi}{2}\\right)$.', '$\\cos\\left(\\pi-\\dfrac{\\pi}{2}\\right) = 0$ et $\\sin\\left(\\pi-\\dfrac{\\pi}{2}\\right) = 1$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos(\\pi-a) = -\\cos(a)$ et $\\sin(\\pi-a) = \\sin(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{2}$, on obtient $\\cos\\left(\\pi-\\dfrac{\\pi}{2}\\right) = 0$ et $\\sin\\left(\\pi-\\dfrac{\\pi}{2}\\right) = 1$.')),
    (1314, "Coordonnées d'un point du cercle trigonométrique", 2, 'On sait que $\\cos\\left(\\dfrac{\\pi}{6}\\right) = \\dfrac{\\sqrt{3}}{2}$ et $\\sin\\left(\\dfrac{\\pi}{6}\\right) = \\dfrac{1}{2}$. En utilisant les symétries du cercle trigonométrique, déterminer $\\cos\\left(-\\dfrac{\\pi}{6}\\right)$.', '$\\cos\\left(-\\dfrac{\\pi}{6}\\right) = \\dfrac{\\sqrt{3}}{2}$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos(-a) = \\cos(a)$ et $\\sin(-a) = -\\sin(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{6}$, on obtient $\\cos\\left(-\\dfrac{\\pi}{6}\\right) = \\dfrac{\\sqrt{3}}{2}$.')),
