    (1335, "Coordonnées d'un point du cercle trigonométrique", 4, "On sait que $\\cos\\left(\\dfrac{\\pi}{2}\\right) = 0$ et $\\sin\\left(\\dfrac{\\pi}{2}\\right) = 1$. En utilisant les symétries du cercle trigonométrique, déterminer $\\cos\\left(\\pi-\\dfrac{\\pi}{2}\\right)$ et $\\sin\\left(\\pi-\\dfrac{\\pi}{2}\\right)$, puis en déduire dans quel quadrant se situe le point du cercle trigonométrique associé à l'angle $\\pi-\\dfrac{\\pi}{2}$.", "$\\cos\\left(\\pi-\\dfrac{\\pi}{2}\\right) = 0$ et $\\sin\\left(\\pi-\\dfrac{\\pi}{2}\\right) = 1$ ; le point est sur l'axe des ordonnées", "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos(\\pi-a) = -\\cos(a)$ et $\\sin(\\pi-a) = \\sin(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{2}$, on obtient $\\cos\\left(\\pi-\\dfrac{\\pi}{2}\\right) = 0$ et $\\sin\\left(\\pi-\\dfrac{\\pi}{2}\\right) = 1$.')),
    (1336, "Coordonnées d'un point du cercle trigonométrique", 4, 'On sait que $\\cos\\left(\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$ et $\\sin\\left(\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$. En utilisant les symétries du cercle trigonométrique, déterminer $\\cos\\left(-\\dfrac{\\pi}{4}\\right)$.', '$\\cos\\left(-\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos(-a) = \\cos(a)$ et $\\sin(-a) = -\\sin(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{4}$, on obtient $\\cos\\left(-\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$.')),
    (1337, "Coordonnées d'un point du cercle trigonométrique", 4, 'On sait que $\\cos\\left(0\\right) = 1$ et $\\sin\\left(0\\right) = 0$. En utilisant les symétries du cercle trigonométrique, déterminer $\\cos\\left(0\\right)$.', '$\\cos\\left(0\\right) = 1$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos(-a) = \\cos(a)$ et $\\sin(-a) = -\\sin(a)$.', 'Étape 2 : Avec $a = 0$, on obtient $\\cos\\left(0\\right) = 1$.')),
    (1338, "Coordonnées d'un point du cercle trigonométrique", 4, 'On sait que $\\cos\\left(0\\right) = 1$ et $\\sin\\left(0\\right) = 0$. En utilisant les symétries du cercle trigonométrique, déterminer $\\sin\\left(\\pi\\right)$.', '$\\sin\\left(\\pi\\right) = 0$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos(\\pi+a) = -\\cos(a)$ et $\\sin(\\pi+a) = -\\sin(a)$.', 'Étape 2 : Avec $a = 0$, on obtient $\\sin\\left(\\pi\\right) = 0$.')),
    (1339, "Coordonnées d'un point du cercle trigonométrique", 4, 'On sait que $\\cos\\left(\\dfrac{\\pi}{2}\\right) = 0$ et $\\sin\\left(\\dfrac{\\pi}{2}\\right) = 1$. En utilisant les symétries du cercle trigonométrique, déterminer $\\sin\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{2}\\right)$.', '$\\sin\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{2}\\right) = 0$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos\\left(\\dfrac{\\pi}{2}-a\\right) = \\sin(a)$ et $\\sin\\left(\\dfrac{\\pi}{2}-a\\right) = \\cos(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{2}$, on obtient $\\sin\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{2}\\right) = 0$.')),
    (1340, "Coordonnées d'un point du cercle trigonométrique", 4, 'On sait que $\\cos\\left(\\dfrac{\\pi}{6}\\right) = \\dfrac{\\sqrt{3}}{2}$ et $\\sin\\left(\\dfrac{\\pi}{6}\\right) = \\dfrac{1}{2}$. En utilisant les symétries du cercle trigonométrique, déterminer $\\sin\\left(-\\dfrac{\\pi}{6}\\right)$.', '$\\sin\\left(-\\dfrac{\\pi}{6}\\right) = -\\dfrac{1}{2}$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos(-a) = \\cos(a)$ et $\\sin(-a) = -\\sin(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{6}$, on obtient $\\sin\\left(-\\dfrac{\\pi}{6}\\right) = -\\dfrac{1}{2}$.')),
    (1341, "Coordonnées d'un point du cercle trigonométrique", 4, 'On sait que $\\cos\\left(\\dfrac{\\pi}{3}\\right) = \\dfrac{1}{2}$ et $\\sin\\left(\\dfrac{\\pi}{3}\\right) = \\dfrac{\\sqrt{3}}{2}$. En utilisant les symétries du cercle trigonométrique, déterminer $\\cos\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{3}\\right)$ et $\\sin\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{3}\\right)$.', '$\\cos\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{3}\\right) = \\dfrac{\\sqrt{3}}{2}$ et $\\sin\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{3}\\right) = \\dfrac{1}{2}$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos\\left(\\dfrac{\\pi}{2}-a\\right) = \\sin(a)$ et $\\sin\\left(\\dfrac{\\pi}{2}-a\\right) = \\cos(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{3}$, on obtient $\\cos\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{3}\\right) = \\dfrac{\\sqrt{3}}{2}$ et $\\sin\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{3}\\right) = \\dfrac{1}{2}$.')),
    (1342, "Coordonnées d'un point du cercle trigonométrique", 4, "On sait que $\\cos\\left(\\dfrac{\\pi}{2}\\right) = 0$ et $\\sin\\left(\\dfrac{\\pi}{2}\\right) = 1$. En utilisant les symétries du cercle trigonométrique, déterminer $\\cos\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{2}\\right)$ et $\\sin\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{2}\\right)$, puis en déduire dans quel quadrant se situe le point du cercle trigonométrique associé à l'angle $\\dfrac{\\pi}{2}-\\dfrac{\\pi}{2}$.", "$\\cos\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{2}\\right) = 1$ et $\\sin\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{2}\\right) = 0$ ; le point est sur l'axe des abscisses", "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos\\left(\\dfrac{\\pi}{2}-a\\right) = \\sin(a)$ et $\\sin\\left(\\dfrac{\\pi}{2}-a\\right) = \\cos(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{2}$, on obtient $\\cos\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{2}\\right) = 1$ et $\\sin\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{2}\\right) = 0$.')),
    (1343, "Coordonnées d'un point du cercle trigonométrique", 4, 'On sait que $\\cos\\left(\\dfrac{\\pi}{3}\\right) = \\dfrac{1}{2}$ et $\\sin\\left(\\dfrac{\\pi}{3}\\right) = \\dfrac{\\sqrt{3}}{2}$. En utilisant les symétries du cercle trigonométrique, déterminer $\\sin\\left(\\pi-\\dfrac{\\pi}{3}\\right)$.', '$\\sin\\left(\\pi-\\dfrac{\\pi}{3}\\right) = \\dfrac{\\sqrt{3}}{2}$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos(\\pi-a) = -\\cos(a)$ et $\\sin(\\pi-a) = \\sin(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{3}$, on obtient $\\sin\\left(\\pi-\\dfrac{\\pi}{3}\\right) = \\dfrac{\\sqrt{3}}{2}$.')),
    (1344, "Coordonnées d'un point du cercle trigonométrique", 4, 'On sait que $\\cos\\left(\\dfrac{\\pi}{6}\\right) = \\dfrac{\\sqrt{3}}{2}$ et $\\sin\\left(\\dfrac{\\pi}{6}\\right) = \\dfrac{1}{2}$. En utilisant les symétries du cercle trigonométrique, déterminer $\\cos\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{6}\\right)$ et $\\sin\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{6}\\right)$.', '$\\cos\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{6}\\right) = \\dfrac{1}{2}$ et $\\sin\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{6}\\right) = \\dfrac{\\sqrt{3}}{2}$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos\\left(\\dfrac{\\pi}{2}-a\\right) = \\sin(a)$ et $\\sin\\left(\\dfrac{\\pi}{2}-a\\right) = \\cos(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{6}$, on obtient $\\cos\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{6}\\right) = \\dfrac{1}{2}$ et $\\sin\\left(\\dfrac{\\pi}{2}-\\dfrac{\\pi}{6}\\right) = \\dfrac{\\sqrt{3}}{2}$.')),
    (1345, "Coordonnées d'un point du cercle trigonométrique", 4, 'On sait que $\\cos\\left(\\dfrac{\\pi}{6}\\right) = \\dfrac{\\sqrt{3}}{2}$ et $\\sin\\left(\\dfrac{\\pi}{6}\\right) = \\dfrac{1}{2}$. En utilisant les symétries du cercle trigonométrique, déterminer $\\cos\\left(\\pi-\\dfrac{\\pi}{6}\\right)$ et $\\sin\\left(\\pi-\\dfrac{\\pi}{6}\\right)$.', '$\\cos\\left(\\pi-\\dfrac{\\pi}{6}\\right) = -\\dfrac{\\sqrt{3}}{2}$ et $\\sin\\left(\\pi-\\dfrac{\\pi}{6}\\right) = \\dfrac{1}{2}$', "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos(\\pi-a) = -\\cos(a)$ et $\\sin(\\pi-a) = \\sin(a)$.', 'Étape 2 : Avec $a = \\dfrac{\\pi}{6}$, on obtient $\\cos\\left(\\pi-\\dfrac{\\pi}{6}\\right) = -\\dfrac{\\sqrt{3}}{2}$ et $\\sin\\left(\\pi-\\dfrac{\\pi}{6}\\right) = \\dfrac{1}{2}$.')),
    (1346, "Coordonnées d'un point du cercle trigonométrique", 5, "On sait que $\\cos\\left(0\\right) = 1$ et $\\sin\\left(0\\right) = 0$. En utilisant les symétries du cercle trigonométrique, déterminer $\\cos\\left(\\pi\\right)$ et $\\sin\\left(\\pi\\right)$, puis en déduire dans quel quadrant se situe le point du cercle trigonométrique associé à l'angle $\\pi$.", "$\\cos\\left(\\pi\\right) = -1$ et $\\sin\\left(\\pi\\right) = 0$ ; le point est sur l'axe des abscisses", "Utiliser les formules donnant le cosinus et le sinus d'angles associés (opposé, supplémentaire, complémentaire...).", ('Étape 1 : On utilise la formule des angles associés : $\\cos(\\pi-a) = -\\cos(a)$ et $\\sin(\\pi-a) = \\sin(a)$.', 'Étape 2 : Avec $a = 0$, on obtient $\\cos\\left(\\pi\\right) = -1$ et $\\sin\\left(\\pi\\right) = 0$.')),
